  args: [
    { name: 'bvid', type: 'string', required: true, help: 'BV id, video URL, or b23.tv short link' },
    { name: 'lang', type: 'string', help: 'Subtitle language code (e.g. zh-CN, en-US, ai-zh). Defaults to the first available.' },
    { name: 'page', type: 'int', help: 'Multi-part (分P) selection, 1-based. Defaults to P1.' },
  ],
  async run({ tab, args }) {
    await ensureOnBili(tab);
    const bvid = await resolveBvid(args.bvid);
    const selectedPage = parsePageArg(args.page);

    const viewData = await biliApi(tab, '/x/web-interface/view', { bvid });
    const cid = selectedPage != null ? selectVideoPart(viewData, selectedPage).cid : viewData?.cid;
    if (!cid) throw errors.upstream(`Could not resolve cid for bvid=${bvid}`);

    const player = await biliApiSigned(tab, '/x/player/wbi/v2', { bvid, cid });
    const needLogin = player?.need_login_subtitle === true;
    const subtitles = player?.subtitle?.subtitles;
    if (!Array.isArray(subtitles)) throw errors.upstream('Bilibili player API returned a malformed subtitle list');
    if (subtitles.length === 0) {
      if (needLogin) throw errors.auth('Subtitles for this video are hidden behind login.');
      throw errors.empty('This video has no subtitles.');
    }

    const target = args.lang ? subtitles.find((s) => s.lan === args.lang) || subtitles[0] : subtitles[0];
    let subUrl = typeof target?.subtitle_url === 'string' ? target.subtitle_url.trim() : '';
    if (!subUrl) throw errors.auth('Empty subtitle_url (risk control or not logged in).');
    if (subUrl.startsWith('//')) subUrl = 'https:' + subUrl;
    if (!/^https?:\/\//i.test(subUrl)) throw errors.upstream(`Invalid subtitle URL: ${subUrl}`);

    const doc = await tab.fetchJson(subUrl);
    const body = Array.isArray(doc?.body) ? doc.body : (Array.isArray(doc) ? doc : null);
    if (!Array.isArray(body)) throw errors.upstream('Subtitle document was not in the expected format');
    if (body.length === 0) throw errors.empty('Subtitle file contained no cues.');

    return body.map((item, idx) => ({
      index: idx + 1,
      from_s: Number(item?.from) || 0,
      to_s: Number(item?.to) || 0,
      content: String(item?.content ?? ''),
    }));
  },
});

import { defineAdapter } from '@jackwener/browsermcp/adapter-sdk';
import { ensureOnBili, biliApiSigned, resolveUid } from './_shared.js';

export default defineAdapter({
  description: 'List a Bilibili user\'s uploaded videos (投稿). Accepts a uid or username.',
  access: 'read',
  domain: 'bilibili.com',
  args: [
    { name: 'uid', type: 'string', required: true, help: 'User uid or username' },
    { name: 'limit', type: 'int', default: 20, help: 'How many videos to return' },
    { name: 'order', type: 'string', default: 'pubdate', choices: ['pubdate', 'click', 'stow'], help: 'Sort by publish date, plays, or favorites' },
    { name: 'page', type: 'int', default: 1, help: 'Page number' },
  ],
  async run({ tab, args }) {
    await ensureOnBili(tab);
    const uid = await resolveUid(tab, String(args.uid));
    const limit = Number(args.limit) || 20;
    const data = await biliApiSigned(tab, '/x/space/wbi/arc/search', {
      mid: uid, pn: Number(args.page) || 1, ps: Math.min(limit, 50), order: args.order || 'pubdate',
    });
    const vlist = data?.list?.vlist ?? [];
    return vlist.slice(0, limit).map((item, i) => ({
      rank: i + 1,
      title: item.title ?? '',
      plays: item.play ?? 0,
      likes: item.like ?? 0,
      published: item.created ? new Date(item.created * 1000).toISOString().slice(0, 10) : '',
      bvid: item.bvid ?? '',
      url: item.bvid ? `https://www.bilibili.com/video/${item.bvid}` : '',
    }));
  },
});

import { getPackageVersion } from '../version.js';
/**
 * MCP server per session: REPL entry, dynamic site tools, diagnostics and cleanup,
 * resources (docs, sites) and prompts — all backed by the same object model.
 */
import { McpServer, ResourceTemplate, type RegisteredTool } from '@modelcontextprotocol/server';
import { z } from 'zod';
import type { Runtime } from '../runtime/runtime.js';
import { createAgentApi, type AgentApi } from '../api/agent.js';
import { ActionError, errorEnvelope } from '../api/errors.js';
import { JsSession, safeStringify } from './js-session.js';
import { buildInstructions, listDocs, readDocForContext, type DocContext } from '../docs/manifest.js';
import { argsToShape, coerceArgs } from '../sites/schema.js';

type Content = Array<{ type: 'text'; text: string } | { type: 'image'; data: string; mimeType: string }>;
type ToolResult = { content: Content; structuredContent?: Record<string, unknown>; isError?: boolean };

function text(s: string): Content[number] { return { type: 'text', text: s }; }
// One result envelope everywhere: success is `{ ok:true, …data }`, failure is `{ ok:false, error:{…} }` — compact JSON,
// in-band `ok` (the agent reads content text), no duplicate structuredContent. Raw strings (docs/markdown) pass through.
function ok(data: unknown, images: Array<{ mimeType: string; base64: string }> = []): ToolResult {
  const content: Content = [];
  if (typeof data === 'string') content.push(text(data));
  else if (Array.isArray(data)) content.push(text(safeStringify({ ok: true, value: data }, 120_000)));
  else if (data && typeof data === 'object') content.push(text(safeStringify({ ok: true, ...(data as Record<string, unknown>) }, 120_000)));
  else content.push(text(safeStringify({ ok: true }, 120_000)));
  for (const img of images) content.push({ type: 'image', data: img.base64, mimeType: img.mimeType });
  return { content };
}
function fail(err: unknown): ToolResult {
  return { content: [text(safeStringify(errorEnvelope(err)))], isError: true };
}
export interface SessionServer { server: McpServer; api: AgentApi; close(): Promise<void> }

export function createMcpServer(rt: Runtime, sessionId: string, opts: { version?: string } = {}): SessionServer {
  const api = createAgentApi(rt, sessionId);
  const state = rt.session(sessionId);
  const docCtx = (): DocContext => ({ backend: rt.backend(), capabilities: rt.features() });
  const availableSites = rt.registry.sites();
  const adapterSummary = availableSites.length
    ? `Available site adapters: ${availableSites.slice(0, 12).map(s => `${s.site} (${s.commands} commands)`).join(', ')}${availableSites.length > 12 ? '; more in sites_search' : ''}.`
    : 'No site adapters are currently loaded. Use browser tools directly; sites_search can check for adapters added later.';
  const adapterInstructions = `${adapterSummary} For a task on a supported site, use sites_search with the site or task to find an existing command, then site_run with its returned arguments. No enable or setup step is required. Prefer a matching adapter over reconstructing the same workflow through clicks or page scripts. Use browser tools for tasks the available commands do not cover. In js, the same entry points are sites.search(query) and sites.run(site, command, args).`;
  const server = new McpServer({ name: 'browsermcp', version: opts.version ?? getPackageVersion() }, {
    capabilities: { tools: { listChanged: true }, resources: { listChanged: true }, prompts: {}, logging: {} },
    instructions: `${adapterInstructions}\n\n${buildInstructions(docCtx())}`,
  });

  const run = async (fn: () => Promise<ToolResult>): Promise<ToolResult> => { try { return await fn(); } catch (err) { return fail(err); } };
  type Extra = { signal?: AbortSignal; _meta?: { progressToken?: string | number }; sendNotification?: (n: { method: 'notifications/progress'; params: { progressToken: string | number; progress: number; total?: number; message?: string } }) => Promise<void> };
  // v2 ServerContext carries request state under `mcpReq` (signal, _meta, notify) — lift the pieces we use.
  const ctxExtra = (ctx: unknown): Extra => {
    const m = (ctx as { mcpReq?: { signal?: AbortSignal; _meta?: { progressToken?: string | number }; notify?: (n: unknown) => Promise<void> } }).mcpReq ?? {};
    return { signal: m.signal, _meta: m._meta, sendNotification: m.notify ? (n) => m.notify!(n) : undefined };
  };
  /** Run a long site command with progress heartbeats (when the host passed a progressToken) and cancellation. */
  const runSiteWithProgress = async (site: string, command: string, args: Record<string, unknown>, extra: Extra): Promise<ToolResult> => {
    const cmd = await rt.registry.resolve(site, command);
    const coerced = coerceArgs(cmd.args, args);
    const token = [REDACTED];
    const started = Date.now();
    let beat: NodeJS.Timeout | undefined;
    if (token !== undefined && extra.sendNotification) {
      beat = setInterval(() => { void extra.sendNotification!({ method: 'notifications/progress', params: { progressToken: token, progress: Math.round((Date.now() - started) / 1000), message: `${site} ${command} running (${Math.round((Date.now() - started) / 1000)}s)` } }).catch(() => {}); }, 5000);
    }
    try {
      const r = await rt.runSite(site, command, coerced, { signal: extra.signal, sessionId });
      if (!r.ok) {
        const { code, message, hint, ...restErr } = r.error;
        return fail(new ActionError(code, message, hint, { site, command, ...restErr }));
      }
      return ok(r.rows !== undefined ? { rows: r.rows, ...(r.nextCursor && { nextCursor: r.nextCursor }) } : { value: r.value });
    } finally { if (beat) clearInterval(beat); }
  };
  for (const [name, command] of Object.entries(api.commands)) {
    server.registerTool(name, {
      description: command.description, inputSchema: command.inputSchema,
      annotations: { readOnlyHint: command.readOnly, destructiveHint: !command.readOnly, openWorldHint: true },
    }, async (input: unknown) => run(async () => {
      if (state.js && state.js.status().state !== 'idle') throw new ActionError('js_busy', 'JavaScript or dispatched API work is still running.', 'Wait for js to finish before using a typed browser command.');
      const value = await command.call(input);
      const { image, ...result } = value as typeof value & { image?: { mimeType: string; base64: string } };
      return ok(result, image ? [image] : []);
    }));
  }
  // ── entry surface: REPL, site commands, discovery and lifecycle ──
  // ── diagnostics & discovery ──
  server.registerTool('doctor', { title: 'Doctor', description: 'Runtime status: browser connection, extension features and protocol warning (if versions differ), site/command counts, sessions. A protocol mismatch blocks browser commands until the host and extension are updated.', inputSchema: {}, annotations: { readOnlyHint: true } }, async () => run(async () => ok({ ...rt.doctor(), javascript: state.js?.status() ?? { state: 'idle', generation: 0, pendingCalls: 0 } })));

  // ── sites ──
  server.registerTool('sites_search', { title: 'Find existing site adapters', description: 'Find reusable site commands before implementing the same task with browser actions or scripts. No query: list available sites with sample commands. With a task, site, or domain as query: find matching commands. Results include args[{name,type,required,help,default,choices}] for site_run. Do not invent parameters.', inputSchema: { query: z.string().optional().describe('task, site, or domain; omit to browse available sites'), limit: z.number().int().min(1).max(100).default(20) }, annotations: { readOnlyHint: true } }, async ({ query, limit }) => run(async () => query?.trim() ? ok({ results: await api.sites.search(query, limit) }) : ok({ sites: rt.registry.sites().slice(0, limit) })));
  server.registerTool('site_run', { title: 'Run a site adapter', description: 'Execute an existing adapter using this session’s browser context. No enable or setup step is required. args must match the args list from sites_search. Invalid args return invalid_args with details.expected. Valid commands execute directly, including writes.', inputSchema: { site: z.string(), command: z.string(), args: z.record(z.string(), z.unknown()).default({}) }, annotations: { openWorldHint: true } }, async ({ site, command, args }, extra) => run(() => runSiteWithProgress(site, command, args, ctxExtra(extra))));

  // ── docs ──
  server.registerTool('docs_get', { title: 'Read a doc', description: 'No name: compact REPL quickstart and available topics. Pass name for a topic; use member with api-reference for one class or method, e.g. Tab.act or Tab.network.', inputSchema: { name: z.string().optional(), member: z.string().optional() }, annotations: { readOnlyHint: true } }, async ({ name, member }) => run(async () => {
    if (!name) return ok(`${readDocForContext('js-tool', docCtx()) ?? ''}\n\nAvailable topics:\n${listDocs(docCtx()).filter(d => d.available).map(d => `- ${d.name}${d.description ? ': ' + d.description : ''}`).join('\n')}`);
    if (member && name !== 'api-reference') throw new ActionError('invalid_args', 'member is supported only with api-reference.');
    if (!listDocs(docCtx()).some((entry) => entry.name === name && entry.available)) throw new ActionError('unknown_doc', `no available doc "${name}"`, 'Call docs_get without a name to see available topics.');
    const d = readDocForContext(name, docCtx(), member);
    if (!d) throw new ActionError('unknown_doc', `no doc "${name}"`, 'Call docs_get without a name to see available topics.');
    return ok(d);
  }));

  // ── code mode ──
  const jsGlobals = { helper: api.helper, agent: api.agent, browser: api.agent.browser, sites: api.sites, recon: api.recon, tools: api.tools, session: api.session };
  server.registerTool('js', {
    title: 'Browser JavaScript REPL', description: 'Primary browser workspace. Persistent Node REPL: variables, functions, classes and top-level await; use let for reusable bindings. Pre-bound browser, sites, tools, recon. Discover and claim an existing tab first; use helper.navigate_tab({tabId, url}) to reuse it. Only open_tab or browser.tabs.new explicitly creates a tab. helper exposes the same typed commands as MCP, including close_tab. observe returns a compact action map, not HTML; follow nextCursor with tab.observe({cursor}) for remaining captured pages, or scope with {target:{selector:"#main"}}. tab.read() returns an object: use result.text and tab.read(result.next) to continue. For focused content use tab.read({target:{role:"main"}}) or an article locator. Wait for SPA content with tab.expect({target:{selector:"article"},visible:true},{timeoutMs:15000}); use a unique target when multiple articles exist. tab.evaluate defaults to 10000 ms; pass timeoutMs for longer work. Reuse tab across calls; await tab.act({action:"click", target:{ref:"..."}}) with an observed ref, then observe. Batch determined steps and return at new decision points. Await API calls; dispatched API work is drained before returning. Ordinary errors preserve bindings. Last expression is returned; do not use top-level return. nodeRepl.write(value) adds output. Page JS uses tab.evaluate. docs_get with no arguments returns quickstart/topics; api-reference with member:"Tab.act" gives exact types.',
    inputSchema: { code: z.string(), timeoutMs: z.number().int().min(1).max(1_800_000).default(300_000), maxChars: z.number().int().min(1000).max(120_000).default(12_000).describe('result text budget; retain large data in a variable and return only relevant parts') },
    annotations: { openWorldHint: true, destructiveHint: true },
  }, async ({ code, timeoutMs, maxChars }, extra) => run(async () => {
    if (!state.js) state.js = new JsSession(jsGlobals, async () => { if (rt.hasFeature('streams')) await rt.browserCommand('streams-reset', { session: `mcp:${sessionId}` }); });
    const changesFrom = state.changes.seq;
    const r = await state.js.run(code, { timeoutMs, signal: ctxExtra(extra).signal });
    await syncSiteTools();
    const changes = await rt.changesSince(sessionId, changesFrom).catch(() => undefined);
    const friction = rt.frictionSince(sessionId, changesFrom);
    const sitesHint = changes?.sites ? { sitesHint: 'Run a listed command with site_run (or await sites.<site>.<command>(args) in js); sites_search returns its arguments.' } : {};
    const content: Content = [];
    if (r.error) {
      // Same coded envelope as every other tool: branchable code/hint/data when the throw was an ActionError, else a generic js_error.
      const e = r.error;
      const env = { ok: false as const, error: { code: e.code ?? 'js_error', message: e.message, ...(e.hint && { hint: e.hint }), ...(e.data && { ...e.data }), ...(!e.code && e.stack && e.name !== 'SyntaxError' && { stack: e.stack.split('\n').slice(0, 4).join('\n') }) }, ...(changes && { changes, ...sitesHint }), ...friction };
      content.push(text(safeStringify(env, maxChars)));
      // changes go before value: a truncated envelope keeps them in its preview
    } else content.push(text(safeStringify({ ok: true, ...(changes && { changes, ...sitesHint }), ...friction, value: r.value === undefined ? null : r.value }, maxChars)));
    if (r.writes.length) {
      const joined = r.writes.join('\n');
      content.push(text(joined.length > 24_000 ? `${joined.slice(0, 24_000)}\n…(truncated ${joined.length - 24_000} chars)` : joined));
    }
    for (const img of r.images) content.push({ type: 'image', data: img.base64, mimeType: img.mimeType });
    return { content, isError: Boolean(r.error) };
  }));
  server.registerTool('js_reset', { title: 'Reset JavaScript session', description: 'Stop JavaScript, clear bindings and close explicit subscriptions; browser tabs stay open. pendingCalls reports already dispatched API operations that may still complete. Wait until doctor shows javascript.pendingCalls:0 before more js; inspect the page before retrying actions.', inputSchema: {} }, async () => run(async () => { return ok(state.js?.reset() ?? { reset: true, pendingCalls: 0 }); }));

  // ── dynamic site tools ──
  const siteTools = new Map<string, { reg: RegisteredTool; metadata: string }>();
  const performSiteToolSync = async (): Promise<void> => {
    const wanted = new Set<string>();
    let changed = false;
    for (const [site, { write }] of state.enabledSites) {
      for (const cmd of await rt.registry.commands(site)) {
        if (!write && cmd.access === 'write') continue;
        const name = `${site}_${cmd.name}`.replace(/[^A-Za-z0-9_-]/g, '_').slice(0, 64);
        wanted.add(name);
        const descriptor = {
          title: `${site} ${cmd.name}`,
          description: `${cmd.description}${cmd.domain ? ` (${cmd.domain})` : ''} [${cmd.access}]${cmd.result ? ` Returns ${cmd.result.kind}: ${cmd.result.description}` : ''}`,
          inputSchema: z.object(argsToShape(cmd.args)).strict(),
          annotations: { readOnlyHint: cmd.access === 'read', destructiveHint: cmd.access === 'write', openWorldHint: true },
          icons: cmd.domain ? [{ src: `https://${cmd.domain.replace(/^https?:\/\//, '').replace(/\/.*$/, '')}/favicon.ico` }] : [],
        };
        const metadata = JSON.stringify({ description: cmd.description, access: cmd.access, domain: cmd.domain, args: cmd.args, result: cmd.result });
        const current = siteTools.get(name);
        if (current) {
          if (current.metadata !== metadata) {
            current.reg.update({ title: descriptor.title, description: descriptor.description, paramsSchema: descriptor.inputSchema, annotations: descriptor.annotations, icons: descriptor.icons });
            current.metadata = metadata;
            changed = true;
          }
          continue;
        }
        const reg = server.registerTool(name, descriptor, async (args, extra) => run(() => runSiteWithProgress(site, cmd.name, args as Record<string, unknown>, ctxExtra(extra))));
        siteTools.set(name, { reg, metadata });
        changed = true;
      }
    }
    for (const [name, { reg }] of siteTools) if (!wanted.has(name)) { reg.remove(); siteTools.delete(name); changed = true; }
    if (changed && server.isConnected()) server.sendToolListChanged();
  };
  let syncTail: Promise<void> = Promise.resolve();
  const syncSiteTools = (): Promise<void> => {
    const next = syncTail.then(performSiteToolSync);
    syncTail = next.catch(() => {});
    return next;
  };
  const onToolsChanged = (): void => { void syncSiteTools().catch((err) => rt.emit('log', `syncSiteTools failed: ${(err as Error).message}`)); };
  rt.on('tools-changed', onToolsChanged);
  const onFeaturesChanged = (): void => { if (server.isConnected()) server.sendResourceListChanged(); };
  rt.on('features-changed', onFeaturesChanged);
  const onLog = (msg: string): void => { if (server.isConnected()) void server.sendLoggingMessage({ level: 'info', logger: 'browsermcp', data: msg }).catch(() => {}); };
  rt.on('log', onLog);
  const onBrowserEvent = (e: { kind: string; session?: string }): void => {
    if (!server.isConnected()) return;
    if (e.session && e.session !== `mcp:${sessionId}`) return;
    // tabs are not exposed as a resource, so tab events don't change any resource list — just relay them on the browser log channel.
    void server.sendLoggingMessage({ level: 'info', logger: 'browser', data: e }).catch(() => {});
  };
  rt.on('browser-event', onBrowserEvent);
  // sites pre-enabled by config apply to every session
  for (const site of rt.configSites) if (rt.registry.has(site)) state.enabledSites.set(site, { write: rt.configSitesWrite.includes(site) });
  if (state.enabledSites.size) queueMicrotask(onToolsChanged);

  // ── resources ──
  server.registerResource('docs', new ResourceTemplate('browsermcp://docs/{name}', { list: async () => ({ resources: listDocs(docCtx()).filter((d) => d.available).map((d) => ({ uri: `browsermcp://docs/${d.name}`, name: d.name, description: d.description, mimeType: 'text/markdown' })) }) }), { title: 'Documentation', description: 'Agent-facing docs' }, async (uri, { name }) => {
    if (!listDocs(docCtx()).some((entry) => entry.name === String(name) && entry.available)) throw new ActionError('unknown_doc', `no available doc "${String(name)}"`);
    return { contents: [{ uri: uri.href, mimeType: 'text/markdown', text: readDocForContext(String(name), docCtx()) ?? `no doc ${String(name)}` }] };
  });
  server.registerResource('sites', 'browsermcp://sites', { title: 'Sites', description: 'All sites with command counts', mimeType: 'application/json' }, async (uri) => ({ contents: [{ uri: uri.href, mimeType: 'application/json', text: JSON.stringify(await api.sites.list(), null, 2) }] }));
  server.registerResource('site', new ResourceTemplate('browsermcp://sites/{site}', { list: undefined }), { title: 'Site commands', mimeType: 'application/json' }, async (uri, { site }) => ({ contents: [{ uri: uri.href, mimeType: 'application/json', text: JSON.stringify((await rt.registry.commands(String(site))).map((c) => ({ name: c.name, description: c.description, access: c.access, domain: c.domain, args: c.args, result: c.result })), null, 2) }] }));

  // ── prompts ──
  server.registerPrompt('browse', { title: 'Browse a site for a goal', description: 'Use the browser service to observe, act, verify, and finalize.', argsSchema: { goal: z.string(), url: z.string().optional() } }, ({ goal, url }) => ({ messages: [{ role: 'user', content: { type: 'text', text: `Goal: ${goal}${url ? `\nStart at: ${url}` : ''}\n\n1. For a supported site, find a matching adapter with sites_search and execute it with site_run.\n2. For other tasks, use tabs_list to reuse or claim an existing tab, then observe → act → verify. navigate_tab reuses that tab; open_tab creates a separate one. Read docs_get when you need API details.\n3. Finish with session_finish, keeping only deliverable/handoff tabs.` } }] }));
  server.registerPrompt('write-tool', { title: 'Turn a flow into a tool', description: 'Explore and verify an API, then define an explicit adapter.', argsSchema: { site: z.string(), goal: z.string() } }, ({ site, goal }) => ({ messages: [{ role: 'user', content: { type: 'text', text: `Create a reusable ${site} adapter for: ${goal}\n\n1. Open the site and perform the flow once. Use tab.network.list/detail in js and recon.discover(tab) to identify candidate endpoints.\n2. Verify the chosen endpoint through the logged-in page, including authentication, arguments, pagination, and errors.\n3. Read docs_get {name:"define-tools"}, use js to define a draft with tools.define, verify it with tools.try using sample args and an output assertion, then publish with tools.activate.` } }] }));

  return {
    server, api,
    close: async () => { rt.off('tools-changed', onToolsChanged); rt.off('features-changed', onFeaturesChanged); rt.off('log', onLog); rt.off('browser-event', onBrowserEvent); await rt.closeSession(sessionId); },
  };
}

/** V8's persistent REPL, accessed through Node's public in-process Inspector API. */
import { Session } from 'node:inspector';
import vm from 'node:vm';
import { createRequire } from 'node:module';
import path from 'node:path';
import { randomUUID } from 'node:crypto';

export async function createEvaluator() {
  const inspector = new Session();
  inspector.connect();
  const post = (method, params = {}) => new Promise((resolve, reject) => {
    inspector.post(method, params, (error, result) => error ? reject(error) : resolve(result));
  });
  let contextId;
  const onContext = ({ params }) => { if (params.context.name === 'browsermcp-repl') contextId = params.context.id; };
  inspector.on('Runtime.executionContextCreated', onContext);
  await post('Runtime.enable');
  const context = vm.createContext({
    require: createRequire(path.join(process.cwd(), 'repl.js')),
  }, { name: 'browsermcp-repl', importModuleDynamically: vm.constants.USE_MAIN_CONTEXT_DEFAULT_LOADER });
  // Keep realm-local JS intrinsics; expose the Node globals provided by this runtime.
  const intrinsics = new Set(vm.runInContext('Object.getOwnPropertyNames(globalThis)', context));
  for (const name of Object.getOwnPropertyNames(globalThis)) {
    if (name === 'global' || intrinsics.has(name)) continue;
    const descriptor = Object.getOwnPropertyDescriptor(globalThis, name);
    if (descriptor.get) descriptor.get = descriptor.get.bind(globalThis);
    if (descriptor.set) descriptor.set = descriptor.set.bind(globalThis);
    Object.defineProperty(context, name, descriptor);
  }
  context.global = context;
  inspector.off('Runtime.executionContextCreated', onContext);
  if (contextId === undefined) throw new Error('Could not create the JavaScript execution context');

  async function unwrap(remote) {
    if (!remote.objectId && !remote.unserializableValue) return remote.value;
    // Transfer the actual reference, preserving API proxies, functions and typed arrays.
    const key = `__browsermcp_result_${randomUUID().replaceAll('-', '')}`;
    try {
      await post('Runtime.callFunctionOn', {
        executionContextId: contextId,
        functionDeclaration: `function(value) { this[${JSON.stringify(key)}] = value; }`,
