  try {
    const tab = await chrome.tabs.get(tabId);
    if (!isDebuggableUrl(tab.url)) {
      // Invalidate cache if previously attached
      attached.delete(tabId);
      throw new Error(`Cannot debug tab ${tabId}: URL is ${tab.url ?? 'unknown'}`);
    }
  } catch (e) {
    // Re-throw our own error, catch only chrome.tabs.get failures
    if (e instanceof Error && e.message.startsWith('Cannot debug tab')) throw e;
    attached.delete(tabId);
    throw new Error(`Tab ${tabId} no longer exists`);
  }

  // Attachment is a fact we track, not something to re-verify per command (the ChatGPT plugin does the same): the
  // `attached` set is kept honest by chrome.debugger.onDetach, and a command that still fails with "not attached"
  // forgets the tab and retries once (see sendDebuggerCommand). A per-command probe cost a round trip and, worse,
  // re-attached while a dialog was open — which dropped the session that owned the dialog's pending callback.
  if (attached.has(tabId)) return;
  const inFlight = attaching.get(tabId);
  if (inFlight) { await inFlight; return; }
  const p = attachNow(tabId, aggressiveRetry).finally(() => { attaching.delete(tabId); });
  attaching.set(tabId, p);
  await p;
}

/** One attach at a time per tab: concurrent commands on a fresh tab share the same attach instead of racing detach/attach. */
const attaching = new Map<number, Promise<void>>();

async function attachNow(tabId: number, aggressiveRetry: boolean): Promise<void> {

  // Retry attach up to 3 times — other extensions (1Password, Playwright MCP Bridge)
  // can temporarily interfere with chrome.debugger. A short delay usually resolves it.
  // Normal commands: 2 retries, 500ms delay (fast fail for non-browser use)
  // Browser commands: 5 retries, 1500ms delay (aggressive, tolerates extension interference)
  const MAX_ATTACH_RETRIES = aggressiveRetry ? 5 : 2;
  const RETRY_DELAY_MS = aggressiveRetry ? 1500 : 500;
  let lastError = '';

  // The forced detach below fires chrome.debugger.onDetach, whose handler wipes
  // this tab's armed network-capture state; detaching also disables the CDP
  // Network domain. Snapshot the capture so we can restore it after a successful
  // re-attach instead of silently dropping in-flight capture — otherwise any
  // non-navigate command that triggers a re-attach (a stale-attach health-check
  // failure during SPA navigation or third-party debugger interference) leaves
  // network-capture-read returning [] even though requests fired.
  const preservedNetworkCapture = networkCaptures.get(tabId);

  for (let attempt = 1; attempt <= MAX_ATTACH_RETRIES; attempt++) {
    try {
      // Force detach first to clear any stale state from other extensions
      try { await chrome.debugger.detach({ tabId }); } catch { /* ignore */ }
      await chrome.debugger.attach({ tabId }, '1.3');
      lastError = '';
      break; // Success
    } catch (e: unknown) {
      lastError = e instanceof Error ? e.message : String(e);
      if (attempt < MAX_ATTACH_RETRIES) {
        console.warn(`[browsermcp] attach attempt ${attempt}/${MAX_ATTACH_RETRIES} failed: ${lastError}, retrying in ${RETRY_DELAY_MS}ms...`);
        await new Promise(resolve => setTimeout(resolve, RETRY_DELAY_MS));
        // Re-verify tab URL before retrying (it may have changed)
        try {
          const tab = await chrome.tabs.get(tabId);
          if (!isDebuggableUrl(tab.url)) {
            lastError = `Tab URL changed to ${tab.url} during retry`;
            break; // Don't retry if URL became un-debuggable
          }
        } catch {
          // Tab is gone — don't fail early here.
          // Later retry layers can re-resolve a fresh automation tab/window.
          lastError = `Tab ${tabId} no longer exists`;
          // Don't break; fall through to retry
        }
      }
    }
  }

  if (lastError) {
    // Log detailed diagnostics for debugging extension conflicts
    let finalUrl = 'unknown';
    let finalWindowId = 'unknown';
    try {
      const tab = await chrome.tabs.get(tabId);
      finalUrl = tab.url ?? 'undefined';
      finalWindowId = String(tab.windowId);
    } catch { /* tab gone */ }
    console.warn(`[browsermcp] attach failed for tab ${tabId}: url=${finalUrl}, windowId=${finalWindowId}, error=${lastError}`);

    const hint = lastError.includes('chrome-extension://')
      ? '. Tip: another Chrome extension may be interfering — try disabling other extensions'
      : '';
    throw new Error(`attach failed: ${lastError}${hint}`);
  }
  attached.add(tabId);

  try {
    await sendDebuggerCommand({ tabId }, 'Runtime.enable');
  } catch {
    // Some pages may not need explicit enable
  }
  // Page events carry javascriptDialogOpening/Closed (dialog tracking) — must be enabled per attach
  await sendDebuggerCommand({ tabId }, 'Page.enable').catch(() => {});
  // Network events tell the post-action settle which requests an action started (see inflight.ts).
  await sendDebuggerCommand({ tabId }, 'Network.enable').catch(() => {});
  // out-of-process iframes announce themselves as child sessions from now on (see trackOopifs)
  await armOopifAutoAttach(tabId);
  // like the ChatGPT plugin: pages gate on document.hasFocus() even when the tab is not the active one
  await sendDebuggerCommand({ tabId }, 'Emulation.setFocusEmulationEnabled', { enabled: true }, 3_000).catch(() => {});

  // Restore network capture that the re-attach (detach + onDetach) tore down.
  // The detach always disables the CDP Network domain, so re-enable it and put
  // the accumulated capture state back unconditionally. Done last (after the
  // awaits above) so it wins over the onDetach handler's delete, which fires
  // while those awaits yield to the event loop.
  if (!preservedNetworkCapture && aggressiveRetry) {
    // Browser tabs capture requests from attachment onward. Adapter tabs opt in explicitly.
    try { await sendDebuggerCommand({ tabId }, 'Network.enable'); networkCaptures.set(tabId, { patterns: [], entries: [], requestToIndex: new Map() }); } catch { /* next start-capture arms it */ }
  }
  if (preservedNetworkCapture) {
    try {
      await sendDebuggerCommand({ tabId }, 'Network.enable');
      networkCaptures.set(tabId, preservedNetworkCapture);
    } catch {
      // Leave capture cleared rather than arm a half-attached Network domain;
      // the next start-capture re-arms cleanly.
    }
  }
}

export function evaluationValue(result?: { type?: string; value?: unknown; unserializableValue?: string }): unknown {
  if (!result || result.type === 'undefined') return null;
  if (result.unserializableValue !== undefined || !Object.prototype.hasOwnProperty.call(result, 'value')) {
    throw Object.assign(new Error('Page result is not JSON-serializable; return plain data rather than a DOM node, function or BigInt.'), { code: 'result_not_serializable' });
  }
  return result.value;
}

export async function evaluate(
  tabId: number,
  expression: string,
  aggressiveRetry: boolean = false,
  timeoutMs: number = CDP_COMMAND_TIMEOUT_MS,
): Promise<unknown> {
  // The host controls command retries. ensureAttached retries attachment locally;
  // a debugger error mid-evaluate invalidates the cache for the next attempt.
  try {
    await ensureAttached(tabId, aggressiveRetry);

    const result = await sendDebuggerCommand({ tabId }, 'Runtime.evaluate', {
      expression,
      returnByValue: true,
      awaitPromise: true,
    }, timeoutMs) as {
      result?: { type: string; value?: unknown; description?: string; subtype?: string };
      exceptionDetails?: { exception?: { description?: string }; text?: string };
    };

    if (result.exceptionDetails) {
      const errMsg = result.exceptionDetails.exception?.description
        || result.exceptionDetails.text
        || 'Eval error';
      throw new Error(errMsg);
    }

    return evaluationValue(result.result);
  } catch (e) {
    const msg = e instanceof Error ? e.message : String(e);
    if (msg.includes('Detached') || msg.includes('Debugger is not attached') || msg.includes('Target closed')) {
      attached.delete(tabId); // Force re-attach on the next command
    }
    throw e;
  }
}

/**
 * Capture a screenshot via CDP Page.captureScreenshot.
 * Returns base64-encoded image data.
 */
export async function screenshot(
  tabId: number,
  options: { format?: 'png' | 'jpeg'; quality?: number; fullPage?: boolean; width?: number; height?: number } = {},
): Promise<string> {
  await ensureAttached(tabId);

  const format = options.format ?? 'png';
  const fullPage = options.fullPage === true;
  const overrideWidth = options.width && options.width > 0 ? Math.ceil(options.width) : undefined;
  // height is ignored under fullPage so the existing measure-from-content path stays unchanged for users who pass --height alongside --full-page.
  const overrideHeight = !fullPage && options.height && options.height > 0 ? Math.ceil(options.height) : undefined;
  const needsOverride = fullPage || overrideWidth !== undefined || overrideHeight !== undefined;

  if (needsOverride) {
    // When width is set, apply it first so layout reflows before we read content size.
    if (overrideWidth !== undefined && fullPage) {
      await sendDebuggerCommand({ tabId }, 'Emulation.setDeviceMetricsOverride', {
        mobile: false,
        width: overrideWidth,
        height: 0,
        deviceScaleFactor: 1,
      });
    }
    let finalWidth = overrideWidth ?? 0;
    let finalHeight = overrideHeight ?? 0;
    if (fullPage) {
      const metrics = await sendDebuggerCommand({ tabId }, 'Page.getLayoutMetrics') as {
        contentSize?: { width: number; height: number };
        cssContentSize?: { width: number; height: number };
      };
      const size = metrics.cssContentSize || metrics.contentSize;
      if (size) {
        if (finalWidth === 0) finalWidth = Math.ceil(size.width);
        finalHeight = Math.ceil(size.height);
      }
    }
    await sendDebuggerCommand({ tabId }, 'Emulation.setDeviceMetricsOverride', {
      mobile: false,
      width: finalWidth,
      height: finalHeight,
      deviceScaleFactor: 1,
    });
  }

  try {
    const params: Record<string, unknown> = { format };
    if (format === 'jpeg' && options.quality !== undefined) {
      params.quality = Math.max(0, Math.min(100, options.quality));
    }

    const result = await sendDebuggerCommand({ tabId }, 'Page.captureScreenshot', params) as {
      data: string; // base64-encoded
    };

    return result.data;
  } finally {
    if (needsOverride) {
      await sendDebuggerCommand({ tabId }, 'Emulation.clearDeviceMetricsOverride').catch(() => {});
    }
  }
}

function downloadResult(item: chrome.downloads.DownloadItem, startedAt: number, event: PageDownloadStart): DownloadWaitResult {
  return {
    downloaded: item.state === 'complete',
    started: true,
    sequence: event.seq,
    suggestedFilename: event.suggestedFilename,
    association: 'url+event',
    id: item.id,
    filename: item.filename,
    url: item.url,
    finalUrl: item.finalUrl,
    mime: item.mime,
    totalBytes: item.totalBytes,
    state: item.state,
    danger: item.danger,
    error: item.error,
    elapsedMs: Date.now() - startedAt,
  };
}

/** Pair the tab's Page event with a new Chrome download observed after the action was armed. */
export async function waitForDownload(tabId: number, afterSequence: number, timeoutMs: number = 30000): Promise<DownloadWaitResult> {
  const startedAt = Date.now();
  const timeout = Math.max(1, timeoutMs);
  const deadline = startedAt + timeout;
  const anchor = pageDownloads.get(tabId)?.anchors.get(afterSequence);
  if (!anchor) return { downloaded: false, started: false, state: 'cursor_expired', error: 'Download cursor is no longer available.', elapsedMs: 0 };
  let event: PageDownloadStart | undefined;
  for (;;) {
    const starts = pageDownloadsAfter(tabId, afterSequence);
    if (starts.length > 1) return { downloaded: false, started: true, state: 'ambiguous', candidates: starts.length, error: 'This action started multiple downloads.', elapsedMs: Date.now() - startedAt };
    event = starts[0];
    if (event) break;
    if (Date.now() >= deadline) return { downloaded: false, started: false, state: 'not_started', elapsedMs: Date.now() - startedAt };
    await new Promise((resolve) => setTimeout(resolve, 150));
  }
  for (;;) {
    const starts = pageDownloadsAfter(tabId, afterSequence);
    if (starts.length > 1) return { downloaded: false, started: true, state: 'ambiguous', candidates: starts.length, error: 'This action started multiple downloads.', elapsedMs: Date.now() - startedAt };
    const matches = chromeDownloads.filter((item) => item.seq > anchor.chromeSeq && (item.url === event.url || item.finalUrl === event.url));
    if (matches.length > 1) return { downloaded: false, started: true, sequence: event.seq, suggestedFilename: event.suggestedFilename, state: 'ambiguous', candidates: matches.length, error: 'Multiple Chrome downloads match the page event.', elapsedMs: Date.now() - startedAt };
    const item = matches[0] ? (await chrome.downloads.search({ id: matches[0].id }))[0] : undefined;
    if (item?.state === 'complete' || item?.state === 'interrupted') return downloadResult(item, startedAt, event);
    if (Date.now() >= deadline) return { downloaded: false, started: true, sequence: event.seq, suggestedFilename: event.suggestedFilename, url: event.url, state: item?.state ?? 'unconfirmed', elapsedMs: Date.now() - startedAt };
    await new Promise((resolve) => setTimeout(resolve, 200));
  }
}

/**
 * Out-of-process iframes (site isolation) are separate targets. A tab-scoped `Target.getTargets` does not list them;
 * what works — and what the ChatGPT plugin does — is `Target.setAutoAttach({flatten:true})` on the tab session, after
 * which Chrome reports every OOPIF child as `Target.attachedToTarget` with its own sessionId. Commands for such a frame
 * are sent on `{tabId, sessionId}`; the frameId of an OOPIF equals its targetId. Nested OOPIFs are auto-attached from
 * their parent session the same way.
 */
interface OopifSession { sessionId: string; targetId: string; url: string; parentSessionId?: string }
const oopifByTab = new Map<number, Map<string, OopifSession>>(); // tabId → targetId(frameId) → session

export function oopifSessions(tabId: number): OopifSession[] { return [...(oopifByTab.get(tabId)?.values() ?? [])]; }

function noteOopif(tabId: number, info: { targetId: string; type: string; url: string }, sessionId: string, parentSessionId?: string): void {
  if (info.type !== 'iframe') return;
  if (!oopifByTab.has(tabId)) oopifByTab.set(tabId, new Map());
  oopifByTab.get(tabId)!.set(info.targetId, { sessionId, targetId: info.targetId, url: info.url, parentSessionId });
  // the child may host further OOPIFs: auto-attach from its session too (Page must be enabled for frame trees)
  void sendDebuggerCommand({ tabId, sessionId } as chrome.debugger.Debuggee, 'Target.setAutoAttach', { autoAttach: true, waitForDebuggerOnStart: false, flatten: true }, 3_000).catch(() => {});
  void sendDebuggerCommand({ tabId, sessionId } as chrome.debugger.Debuggee, 'Page.enable', undefined, 3_000).catch(() => {});
}

/** Called once from registerListeners: keep the OOPIF map honest from Target events on the tab and its child sessions. */
function trackOopifs(source: chrome.debugger.Debuggee, method: string, params: any): void {
  const tabId = source.tabId; if (!tabId) return;
  if (method === 'Target.attachedToTarget' && params?.sessionId && params?.targetInfo) noteOopif(tabId, params.targetInfo, params.sessionId, (source as { sessionId?: string }).sessionId);
  else if (method === 'Target.detachedFromTarget' && params?.targetId) oopifByTab.get(tabId)?.delete(params.targetId);
  else if (method === 'Target.targetInfoChanged' && params?.targetInfo?.targetId) { const e = oopifByTab.get(tabId)?.get(params.targetInfo.targetId); if (e) e.url = params.targetInfo.url; }
}

/** Auto-attach is armed at tab attach (see attachNow) so OOPIF sessions exist before anyone asks for them. */
export async function armOopifAutoAttach(tabId: number): Promise<void> {
  await sendDebuggerCommand({ tabId }, 'Target.setAutoAttach', { autoAttach: true, waitForDebuggerOnStart: false, flatten: true }, 3_000).catch((e) => console.warn(`[browsermcp] Target.setAutoAttach failed for tab ${tabId}: ${e instanceof Error ? e.message : String(e)}`));
}

/** Sessions we opened ourselves by attaching to the iframe target (the plugin's approach); keyed `${tabId}:${frameId}`. */
const directTargets = new Map<string, string>();

/** Debuggee for a frame's own session: a tracked auto-attached child session, else a direct attachment to the iframe target. */
async function frameDebuggee(tabId: number, frameId: string, aggressiveRetry = false): Promise<chrome.debugger.Debuggee> {
  const tracked = oopifByTab.get(tabId)?.get(frameId);
  if (tracked) return { tabId, sessionId: tracked.sessionId } as chrome.debugger.Debuggee;
  const key = `${tabId}:${frameId}`;
  if (directTargets.has(key)) return { targetId: frameId } as chrome.debugger.Debuggee;
  await ensureAttached(tabId, aggressiveRetry);
  try { await chrome.debugger.attach({ targetId: frameId } as chrome.debugger.Debuggee, '1.3'); }
  catch (e) { const msg = e instanceof Error ? e.message : String(e); if (!/already attached/i.test(msg)) throw Object.assign(new Error(`frame ${frameId} has no attachable target: ${msg}`), { code: 'frame_unreachable' }); }
  directTargets.set(key, frameId);
  return { targetId: frameId } as chrome.debugger.Debuggee;
}

/** True when the frame renders in its own process (has an auto-attached iframe session); false for in-process frames. */
export async function hasFrameTarget(tabId: number, frameId: string, aggressiveRetry = false): Promise<boolean> {
  try { await frameDebuggee(tabId, frameId, aggressiveRetry); return true; } catch { return false; }
}

export async function sendCommandInFrameTarget(
  tabId: number,
  frameId: string,
  method: string,
  params: Record<string, unknown> = {},
  aggressiveRetry: boolean = false,
  timeoutMs: number = CDP_COMMAND_TIMEOUT_MS,
): Promise<unknown> {
  const target = await frameDebuggee(tabId, frameId, aggressiveRetry);
  return sendDebuggerCommand(target, method, params, timeoutMs);
}

export interface FrameEntry { index: number; frameId: string; url: string; name: string; crossOrigin: boolean; /** lives in its own renderer process (site isolation) */ oopif: boolean }
type FrameNode = { frame: { id: string; url: string; name?: string }; childFrames?: FrameNode[] };

/**
 * Every child frame of the tab in one stable list: the root session's frame tree (in-process frames, document order)
 * merged with the tab's out-of-process iframe targets, each with its own subtree. Under site isolation an OOPIF is a
 * separate target and never appears in the root tree, so enumeration and frame-scoped evaluate must share this list.
 */
export async function listFrames(tabId: number): Promise<FrameEntry[]> {
  await ensureAttached(tabId);
  const origin = (u: string) => { try { return new URL(u).origin; } catch { return null; } };
  const out: FrameEntry[] = [];
  const seen = new Set<string>();
  const { frameTree: root } = await sendDebuggerCommand({ tabId }, 'Page.getFrameTree') as { frameTree: FrameNode };
  const top = origin(root.frame.url);
  const inTree = new Map<string, FrameNode['frame']>();
  const index = (node: FrameNode) => { for (const c of node.childFrames ?? []) { inTree.set(c.frame.id, c.frame); index(c); } };
  index(root);
  seen.add(root.frame.id);
  const push = (f: { id: string; url: string; name?: string }, oopif: boolean) => {
    if (seen.has(f.id)) return; seen.add(f.id);
    const o = origin(f.url);
    out.push({ index: out.length, frameId: f.id, url: f.url, name: f.name ?? '', crossOrigin: oopif || o === null || o === 'null' || o !== top, oopif });
  };
  // Frames come from the DOM in document order: every <iframe>/<frame> node carries its frameId, in-process or not
  // (a tab-scoped Target.getTargets does not list out-of-process iframes; the root frame tree does not contain them).
  type DomNode = { nodeName?: string; frameId?: string; children?: DomNode[]; contentDocument?: DomNode; shadowRoots?: DomNode[] };
  const iframeIds = (doc: DomNode): string[] => {
    const ids: string[] = [];
    const walk = (n: DomNode) => { if ((n.nodeName === 'IFRAME' || n.nodeName === 'FRAME') && n.frameId) ids.push(n.frameId); for (const c of n.children ?? []) walk(c); for (const c of n.shadowRoots ?? []) walk(c); if (n.contentDocument) walk(n.contentDocument); };
    walk(doc);
    return ids;
  };
  const visit = async (target: chrome.debugger.Debuggee, oopif: boolean, depth: number): Promise<void> => {
    if (depth > 4) return;
    let ids: string[] = [];
    try { const { root: doc } = await sendDebuggerCommand(target, 'DOM.getDocument', { depth: -1, pierce: true }, 5_000) as { root: DomNode }; ids = iframeIds(doc); } catch { return; }
    for (const id of ids) {
      if (seen.has(id)) continue;
      const known = inTree.get(id);
      if (known) { push(known, oopif); continue; } // in-process (relative to this session): described by the frame tree
      // not in this session's tree → its own process: attach to the iframe target (targetId == frameId) and read its tree
      try {
        const child = await frameDebuggee(tabId, id);
        const { frameTree } = await sendDebuggerCommand(child, 'Page.getFrameTree', undefined, 3_000) as { frameTree: FrameNode };
        push({ id, url: frameTree.frame.url, name: frameTree.frame.name }, true);
        const sub = (n: FrameNode) => { for (const c of n.childFrames ?? []) { inTree.set(c.frame.id, c.frame); sub(c); } };
        sub(frameTree);
        await visit(child, true, depth + 1);
      } catch (e) {
        push({ id, url: '' }, true);
        console.warn(`[browsermcp] frame ${id}: ${e instanceof Error ? e.message : String(e)}`);
      }
    }
  };
  await visit({ tabId }, false, 0);
  return out;
}

function normalizeCapturePatterns(pattern?: string): string[] {
  return String(pattern || '')
    .split('|')
    .map((part) => part.trim())
    .filter(Boolean);
}

function shouldCaptureUrl(url: string | undefined, patterns: string[]): boolean {
  if (!url) return false;
  if (!patterns.length) return true;
  return patterns.some((pattern) => url.includes(pattern));
}

function normalizeHeaders(headers: unknown): Record<string, string> {
  if (!headers || typeof headers !== 'object') return {};
  const out: Record<string, string> = {};
  for (const [key, value] of Object.entries(headers as Record<string, unknown>)) {
    out[String(key)] = String(value);
  }
  return out;
}

function getOrCreateNetworkCaptureEntry(tabId: number, requestId: string, fallback?: {
  url?: string;
  method?: string;
  requestHeaders?: Record<string, string>;
  resourceType?: string;
}): NetworkCaptureEntry | null {
  const state = networkCaptures.get(tabId);
  if (!state) return null;
  const existingIndex = state.requestToIndex.get(requestId);
  if (existingIndex !== undefined) {
    return state.entries[existingIndex] || null;
  }
  const url = fallback?.url || '';
  if (!shouldCaptureUrl(url, state.patterns)) return null;
  if (fallback?.resourceType && !CAPTURED_TYPES.has(fallback.resourceType)) return null;
  if (/^(data|blob|chrome-extension):/.test(url)) return null;
  if (state.entries.length >= CAPTURE_MAX_ENTRIES) {
    // drop the oldest third; rebuild the index so in-flight requests keep resolving
    const drop = Math.floor(CAPTURE_MAX_ENTRIES / 3);
    state.entries.splice(0, drop);
    for (const [rid, idx] of [...state.requestToIndex]) { if (idx < drop) state.requestToIndex.delete(rid); else state.requestToIndex.set(rid, idx - drop); }
  }
  const entry: NetworkCaptureEntry = {
    kind: 'cdp',
    requestId,
    url,
    method: fallback?.method || 'GET',
    resourceType: fallback?.resourceType,
    requestHeaders: fallback?.requestHeaders || {},
    timestamp: Date.now(),
  };
  state.entries.push(entry);
  state.requestToIndex.set(requestId, state.entries.length - 1);
  return entry;
}

export async function startNetworkCapture(
  tabId: number,
  pattern?: string,
): Promise<void> {
  await ensureAttached(tabId);
  await sendDebuggerCommand({ tabId }, 'Network.enable');
  networkCaptures.set(tabId, {
    patterns: normalizeCapturePatterns(pattern),
    entries: [],
    requestToIndex: new Map(),
  });
}

/** Hand out the finished entries and keep the in-flight ones: the host drains after every goto/act, and an entry drained
 * before its response arrived would never get its status, content type and body (response events are lookup-only). */
export async function readNetworkCapture(tabId: number): Promise<NetworkCaptureEntry[]> {
  const state = networkCaptures.get(tabId);
  if (!state) return [];
  const out: NetworkCaptureEntry[] = []; const keep: NetworkCaptureEntry[] = []; const keepIds = new Map<string, number>();
  const idOf = new Map<number, string>(); for (const [rid, idx] of state.requestToIndex) idOf.set(idx, rid);
  const stale = Date.now() - 60_000; // a request with no end event after a minute is handed out as it is
  state.entries.forEach((e, idx) => {
    if (e.done || e.timestamp < stale) { out.push(e); return; }
    const rid = idOf.get(idx); if (rid) keepIds.set(rid, keep.length); keep.push(e);
  });
  state.entries = keep; state.requestToIndex = keepIds;
  return out;
}

export function hasActiveNetworkCapture(tabId: number): boolean {
  return networkCaptures.has(tabId);
}


export async function detach(tabId: number): Promise<void> {
  oopifByTab.delete(tabId);
  if (!attached.has(tabId)) return;
  attached.delete(tabId);
  networkCaptures.delete(tabId);
  try { await chrome.debugger.detach({ tabId }); } catch { /* ignore */ }
}

export function registerListeners(): void {
  chrome.downloads.onCreated.addListener((item) => {
    chromeDownloads.push({ seq: ++chromeDownloadSeq, id: item.id, url: item.url, finalUrl: item.finalUrl });
    if (chromeDownloads.length > 200) chromeDownloads.splice(0, chromeDownloads.length - 200);
  });
  chrome.debugger.onEvent.addListener((source, method, params: any) => {
    if (!source.tabId) return;
    if (method.startsWith('Network.') && !(source as { sessionId?: string }).sessionId) noteNetworkEvent(source.tabId, method, params);
    if (method.startsWith('Target.')) { trackOopifs(source, method, params); return; }
    if (method === 'Page.downloadWillBegin') { notePageDownload(source.tabId, params ?? {}); return; }
    if (method === 'Runtime.consoleAPICalled') {
      const t = String(params?.type ?? 'log'); const level = (t === 'warning' ? 'warn' : ['debug', 'info', 'log', 'warn', 'error'].includes(t) ? t : 'log') as ConsoleEntry['level'];
      const frame = params?.stackTrace?.callFrames?.[0];
      noteConsole(source.tabId, level, ((params?.args ?? []) as Array<{ type?: string; value?: unknown; description?: string }>).map(describeRemoteObject).join(' '), frame?.url, frame?.lineNumber);
      return;
    }
    if (method === 'Runtime.exceptionThrown') {
      const d = params?.exceptionDetails ?? {};
      noteConsole(source.tabId, 'error', `Uncaught ${d.exception?.description ?? d.text ?? 'exception'}`, d.url, d.lineNumber);
      return;
    }
    if (method === 'Page.javascriptDialogOpening') { if (!dialogs.has(source.tabId)) noteDialog(source.tabId, { type: params?.type ?? 'alert', message: String(params?.message ?? ''), defaultPrompt: params?.defaultPrompt, url: params?.url, openedAt: Date.now(), sessionId: source.sessionId }); }
    else if (method === 'Page.javascriptDialogClosed') noteDialog(source.tabId, null);
  });
  chrome.tabs.onRemoved.addListener((tabId) => {
    consoleLogs.delete(tabId);
    for (const k of [...directTargets.keys()]) if (k.startsWith(`${tabId}:`)) directTargets.delete(k);
    dialogs.delete(tabId); dialogWaiters.delete(tabId); dialogClosedWaiters.delete(tabId);
    attached.delete(tabId);
    networkCaptures.delete(tabId);
    pageDownloads.delete(tabId);
    forgetTab(tabId);
      oopifByTab.delete(tabId);
  });
  chrome.debugger.onDetach.addListener((source) => {
    const sessionId = (source as { sessionId?: string }).sessionId;
    if (source.tabId && sessionId) {
      // a child (OOPIF) session went away — e.g. its frame navigated; the tab's root attachment is untouched
      const m = oopifByTab.get(source.tabId);
      if (m) for (const [id, s] of m) if (s.sessionId === sessionId) m.delete(id);
      return;
    }
    if (source.tabId) {
      consoleLogs.delete(source.tabId);
      dialogs.delete(source.tabId);
      attached.delete(source.tabId);
      networkCaptures.delete(source.tabId);
      oopifByTab.delete(source.tabId);
      forgetTab(source.tabId);
      for (const k of [...directTargets.keys()]) if (k.startsWith(`${source.tabId}:`)) directTargets.delete(k);
      return;
    }
    if ((source as { targetId?: string }).targetId) { const tid = (source as { targetId?: string }).targetId!; for (const [k, v] of directTargets) if (v === tid) directTargets.delete(k); return; }
  });
  // Invalidate attached cache when tab URL changes to non-debuggable
  chrome.tabs.onUpdated.addListener(async (tabId, info) => {
    if (info.url && !isDebuggableUrl(info.url)) {
      await detach(tabId);
    }
  });
  chrome.debugger.onEvent.addListener(async (source, method, params) => {
    const tabId = source.tabId;
    if (!tabId) return;
    const state = networkCaptures.get(tabId);
    if (!state) return;
    const eventParams = params as Record<string, any> | undefined;

    if (method === 'Network.requestWillBeSent') {
      const requestId = String(eventParams?.requestId || '');
      const request = eventParams?.request as {
        url?: string;
        method?: string;
        headers?: Record<string, unknown>;
        postData?: string;
        hasPostData?: boolean;
      } | undefined;
      const entry = getOrCreateNetworkCaptureEntry(tabId, requestId, {
        url: request?.url,
        method: request?.method,
        requestHeaders: normalizeHeaders(request?.headers),
        resourceType: typeof eventParams?.type === 'string' ? eventParams.type : undefined,
      });
      if (!entry) return;
      // On an HTTP 30x, CDP re-fires requestWillBeSent with the SAME requestId
      // (the prior hop is carried in `redirectResponse`) for the redirect
      // target — typically a GET with no postData. Overwriting the body here
      // would wipe the original request's captured POST body, so only populate
      // the body on the initial send.
      if (!eventParams?.redirectResponse) {
        entry.requestBodyKind = request?.hasPostData ? 'string' : 'empty';
        {
          const raw = String(request?.postData || '');
          const fullSize = raw.length;
          const truncated = fullSize > CDP_REQUEST_BODY_CAPTURE_LIMIT;
          entry.requestBodyPreview = truncated ? raw.slice(0, CDP_REQUEST_BODY_CAPTURE_LIMIT) : raw;
          entry.requestBodyFullSize = fullSize;
          entry.requestBodyTruncated = truncated;
        }
        try {
          const postData = await sendDebuggerCommand({ tabId }, 'Network.getRequestPostData', { requestId }) as { postData?: string };
          if (postData?.postData) {
            const raw = postData.postData;
            const fullSize = raw.length;
            const truncated = fullSize > CDP_REQUEST_BODY_CAPTURE_LIMIT;
            entry.requestBodyKind = 'string';
            entry.requestBodyPreview = truncated ? raw.slice(0, CDP_REQUEST_BODY_CAPTURE_LIMIT) : raw;
            entry.requestBodyFullSize = fullSize;
            entry.requestBodyTruncated = truncated;
          }
        } catch {
          // Optional; some requests do not expose postData.
        }
      }
      return;
    }

    if (method === 'Network.responseReceived') {
      const requestId = String(eventParams?.requestId || '');
      const response = eventParams?.response as {
        url?: string;
        mimeType?: string;
        status?: number;
        headers?: Record<string, unknown>;
      } | undefined;
      // Lookup-only (like loadingFinished below): never create an entry from a
      // response. If the matching requestWillBeSent was already drained by a
      // readNetworkCapture() while the request was in flight, creating one here
      // produces an orphan half-entry with a defaulted method ('GET') and no
      // request data.
      const stateEntryIndex = state.requestToIndex.get(requestId);
      if (stateEntryIndex === undefined) return;
      const entry = state.entries[stateEntryIndex];
      if (!entry) return;
      entry.responseStatus = response?.status;
      entry.responseContentType = response?.mimeType || '';
      entry.responseHeaders = normalizeHeaders(response?.headers);
      return;
    }

    if (method === 'Network.loadingFailed') {
      const requestId = String(eventParams?.requestId || '');
      const stateEntryIndex = state.requestToIndex.get(requestId);
      const entry = stateEntryIndex === undefined ? undefined : state.entries[stateEntryIndex];
      if (entry) entry.done = true;
      return;
    }
    if (method === 'Network.loadingFinished') {
      const requestId = String(eventParams?.requestId || '');
      const stateEntryIndex = state.requestToIndex.get(requestId);
      if (stateEntryIndex === undefined) return;
      const entry = state.entries[stateEntryIndex];
      if (!entry) return;
      const finish = () => { entry.done = true; };
      // bodies only for what can carry data: JSON-ish XHR/fetch and documents; assets were filtered at request time
      if (entry.responseContentType && !/json|graphql|x-component|text\/plain|javascript|html|xml/i.test(entry.responseContentType)) { finish(); return; }
      try {
        const body = await sendDebuggerCommand({ tabId }, 'Network.getResponseBody', { requestId }) as {
          body?: string;
          base64Encoded?: boolean;
        };
        if (typeof body?.body === 'string') {
          const fullSize = body.body.length;
          const truncated = fullSize > CDP_RESPONSE_BODY_CAPTURE_LIMIT;
          const stored = truncated ? body.body.slice(0, CDP_RESPONSE_BODY_CAPTURE_LIMIT) : body.body;
          entry.responsePreview = body.base64Encoded ? `base64:${stored}` : stored;
          entry.responseBodyFullSize = fullSize;
          entry.responseBodyTruncated = truncated;
        }
      } catch {
        // Optional; bodies are unavailable for some requests (e.g. uploads).
      }
      finish();
    }
  });
}

/** A page handle is Chrome's tab id, stable across navigation for the tab's lifetime. */
export function pageId(tabId: number): string {
  if (!Number.isSafeInteger(tabId) || tabId < 0) throw new Error(`Invalid tab id: ${tabId}`);
  return String(tabId);
}

/** Resolve only a live tab. Session ownership is checked by the caller. */
export async function resolveTabId(page: string): Promise<number> {
  const tabId = Number(page);
  if (!Number.isSafeInteger(tabId) || tabId < 0 || String(tabId) !== page) throw new Error(`Invalid page handle: ${page}`);
  await chrome.tabs.get(tabId);
  return tabId;
}

// Adapted from OpenCLI 1.8.7 (https://github.com/jackwener/opencli), Apache-2.0.
// Kept only the page scripts used by browsermcp; see LICENSE.

/**
 * Wrap JS code for CDP Runtime.evaluate:
 * - Already an IIFE `(...)()` → send as-is
 * - Arrow/function literal → wrap as IIFE `(code)()`
 * - `new Promise(...)` or raw expression → send as-is (expression)
 */
export function wrapForEval(js: string): string {
    if (typeof js !== 'string')
        return 'undefined';
    const code = js.trim();
    if (!code)
        return 'undefined';
    // Already an IIFE: `(async () => { ... })()` or `(function() {...})()`
    if (/^\([\s\S]*\)\s*\(.*\)\s*$/.test(code))
        return code;
    // Arrow function: `() => ...` or `async () => ...`
    if (/^(async\s+)?(\([^)]*\)|[A-Za-z_]\w*)\s*=>/.test(code))
        return `(${code})()`;
    // Function declaration: `function ...` or `async function ...`
    if (/^(async\s+)?function[\s(]/.test(code))
        return `(${code})()`;
    // Everything else: bare expression, `new Promise(...)`, etc. → evaluate directly
    return code;
}

/** Generate JS to read performance resource entries as network requests */
export function networkRequestsJs(includeStatic: boolean): string {
    return `
    (() => {
      const entries = performance.getEntriesByType('resource');
      return entries
        ${includeStatic ? '' : '.filter(e => !["img", "font", "css", "script"].some(t => e.initiatorType === t))'}
        .map(e => ({
          url: e.name,
          type: e.initiatorType,
          duration: Math.round(e.duration),
          size: e.transferSize || 0,
        }));
    })()
  `;
}
/**
 * Generate JS to wait until the DOM stabilizes (no mutations for `quietMs`),
 * with a hard cap at `maxMs`. Uses MutationObserver in the browser.
 *
 * Returns as soon as the page stops changing, avoiding unnecessary fixed waits.
 * If document.body is not available, falls back to a fixed sleep of maxMs.
 */
export function waitForDomStableJs(maxMs: number, quietMs: number): string {
    return `
    new Promise(resolve => {
      if (!document.body) {
        setTimeout(() => resolve('nobody'), ${maxMs});
        return;
      }
      let timer = null;
      let cap = null;
      const done = (reason) => {
        clearTimeout(timer);
        clearTimeout(cap);
        obs.disconnect();
        resolve(reason);
      };
      const resetQuiet = () => {
        clearTimeout(timer);
        timer = setTimeout(() => done('quiet'), ${quietMs});
      };
      const obs = new MutationObserver(resetQuiet);
      obs.observe(document.body, { childList: true, subtree: true, attributes: true });
      resetQuiet();
      cap = setTimeout(() => done('capped'), ${maxMs});
    })
  `;
}

import type { BrowserBackend } from '../backends/backend.js';
import type { ManagedRuntimePage } from '../backends/managed-page.js';
/**
 * Runtime — the resident kernel: site registry, per-MCP-session state, and page backends.
 * Lives inside the Chrome-spawned host. The stdio launcher proxies to this runtime.
 */
import type { ObserveResult } from '../api/tab.js';
import { EventEmitter } from 'node:events';
import type { ExtensionBridge } from '../host/bridge.js';
import type { BrowserEvent } from '../protocol.js';
import { PROTOCOL_REVISION, type BrowserFeature } from '../protocol.js';
import { SiteRegistry, type AdapterCommand, type Source } from '../sites/loader.js';
import { runAdapter, type CommandRunResult, type CommandRunError, type PageProvider } from '../sites/executor.js';
import { AsyncLocalStorage } from 'node:async_hooks';
import { listDefinedTools, ensureUserSource, deleteTool, type ToolDefinition } from '../sites/define.js';
import { createDraftStore, type DraftStore, type DraftExpectation } from '../sites/drafts.js';
import { createExtensionPage } from '../backends/extension-page.js';
import type { RuntimePage } from '../backends/page-types.js';
import { JsSession } from '../mcp/js-session.js';
import { Tab, createAgentApi, type AgentApi } from '../api/agent.js';

export type Backend = 'extension' | 'electron' | 'none';

export interface RuntimeOptions {
  bridge?: ExtensionBridge | null;
  backend?: BrowserBackend;
  sources?: Source[];
  userAdaptersDir?: string | null;
  sites?: string[];
  sitesWrite?: string[];
  cursor?: boolean;
  log?: (msg: string) => void;
}

export interface SessionState {
  id: string;
  name?: string;
  createdAt: number;
  browserPage?: RuntimePage;
  browserPagePromise?: Promise<RuntimePage>;
  /** One page object per tab (same bridge, own identity); the session page above carries no tab and serves session-scope calls. */
  pages: Map<string, RuntimePage>;
  /** Per-tab serialization of page operations. */
  tabLocks: Map<string, Promise<void>>;
  enabledSites: Map<string, { write: boolean }>;
  capabilities: Set<string>;
  js?: JsSession;
  observationSeq: number;
  /** Most recent immutable observation per tab; replaced on fresh capture, cleared on release. */
  observations: Map<string, ObserveResult>;
  webmcpCatalogs: Map<string, string>;
  /** Document namespace → frame route, shared by handles for the same tab. */
  refFrames: Map<string, Map<string, import('../protocol.js').FrameStep[]>>;
  lastObserve: Map<string, { id: string; text: string }>;
  /** Network entries seen per tab, with monotonically increasing sequence numbers for cursor-based reads. */
  netLog: Map<string, { seq: number; entries: Array<Record<string, unknown> & { seq: number }>; seen: Set<string>; bodyChars: number }>;
  /** Side effects seen in this session, in order; each js call reports the ones recorded while it ran. */
  changes: { seq: number; entries: Array<SessionChange & { seq: number }> };
  /** Sites whose adapters were already suggested to this session. */
  suggestedSites: Set<string>;
  /** Tabs this session flagged as needing the user (reportIssue); cleared when the agent next uses the tab. */
  attention: Map<string, PageIssue & { atRun: number }>;
  /** Last failed tab.act per tab, so a following evaluate or dom click on that tab is reported as a fallback. */
  actFailures: Map<string, { run: number; code: string; target?: string }>;
  finalized: boolean;
}

/** A problem a page shows the agent: detected from the main document's HTTP status, or reported by the agent with tab.reportIssue. */
export type IssueCode = 'auth_required' | 'blocked' | 'rate_limited' | 'http_error' | 'error_page';
export interface PageIssue { code: IssueCode; source: 'detected' | 'agent'; url?: string; status?: number; retryAfterMs?: number; note?: string }
export type SessionChange =
  | { kind: 'opened'; tab: string; tabId: number; url?: string }
  | { kind: 'closed'; tab: string; tabId: number }
  | { kind: 'navigated'; tab: string; url?: string }
  | { kind: 'dialog'; tab: string; dialogType: string; message?: string }
  | { kind: 'issue'; tab: string; issue: PageIssue }
  | { kind: 'toolError'; error: ToolError }
  | { kind: 'fallback'; fallback: ToolFallback };
const MAX_CHANGES = 200;
/** An error a browser API call raised during a js call, whether or not the code caught it. */
export interface ToolError { code: string; api: string; tab?: string; action?: string; target?: string; retryable: boolean }
/** The code took another route after a tool failed on the same tab, e.g. tab.act failed and tab.evaluate followed. */
export interface ToolFallback { from: string; to: string; tab: string; code: string; target?: string }
/** What a js call's result reports about tool friction; absent when nothing failed. */
export interface ToolFriction { toolErrors?: ToolError[]; fallbacks?: ToolFallback[] }
/** Reported with each js call that caused it. Absent fields mean nothing of that kind happened. */
export interface ChangeSummary {
  opened?: Array<{ tab: string; url?: string }>;
  navigated?: Array<{ tab: string; url?: string }>;
  closed?: string[];
  dialogs?: Array<{ tab: string; type: string; message?: string }>;
  issues?: Array<PageIssue & { tab: string }>;
  /** Ready-made commands for a site this session just reached; suggested once per session. */
  sites?: Array<{ site: string; commands: string[]; more?: number }>;
}

export interface DoctorReport {
  backend: Backend;
  browser: { connected: boolean; features: BrowserFeature[] };
  extension: { connected: boolean; protocolMatches: boolean | null; protocolWarning: string | null; version: string | null; protocolRevision: number | null; hostProtocolRevision: number; features: BrowserFeature[] };
  sites: number;
  commands: number;
  definedTools: number;
  sessions: number;
  cursor: boolean;
}

export interface RuntimeEvents {
  'browser-event': [BrowserEvent];
  'features-changed': [BrowserFeature[]];
  'tools-changed': [{ site?: string }];
  log: [string];
}

export class Runtime extends EventEmitter<RuntimeEvents> implements PageProvider {
  readonly registry: SiteRegistry;
  readonly userAdaptersDir: string | null;
  private readonly drafts: DraftStore | null;
  readonly sessions = new Map<string, SessionState>();
  private readonly adapterRuns = new Map<string, Promise<void>>();
  private readonly adapterCallContext = new AsyncLocalStorage<{ sites: Set<string>; retired: boolean; sessionId?: string }>();
  private readonly siteApis = new Map<string, AgentApi>();
  bridge: ExtensionBridge | null;
  private readonly browserBackend?: BrowserBackend;
  private readonly unsubscribeBackend?: () => void;
  readonly cursorEnabled: boolean;
  readonly configSites: string[];
  readonly configSitesWrite: string[];
  readonly startedAt = Date.now();

  constructor(opts: RuntimeOptions = {}) {
    super();
    this.userAdaptersDir = opts.userAdaptersDir ?? null;
    const sources = [...(opts.sources ?? [])];
    if (this.userAdaptersDir && !sources.some(source => source.dir === this.userAdaptersDir)) sources.push({ dir: this.userAdaptersDir, kind: 'user' });
    this.registry = new SiteRegistry(sources);
    this.drafts = this.userAdaptersDir ? createDraftStore(this.userAdaptersDir) : null;
    this.bridge = opts.bridge ?? null;
    this.browserBackend = opts.backend;
    this.cursorEnabled = opts.cursor ?? false;
    this.configSites = opts.sites ?? [];
    this.configSitesWrite = opts.sitesWrite ?? [];
    if (opts.log) this.on('log', opts.log);
    const onEvent = (e: BrowserEvent): void => {
      if ('page' in e && e.page && 'session' in e) {
        const id = e.session.replace(/^mcp:/, ''); const state = this.sessions.get(id);
        if (e.kind === 'tab_closed' || e.kind === 'tab_released' || e.kind === 'tab_detached' || e.kind === 'tab_attached') this.forgetPage(id, e.page);
        if (e.kind === 'tab_navigated' && state) for (const key of state.lastObserve.keys()) if (key.startsWith(`${e.page}:`)) state.lastObserve.delete(key);
        if (state) {
          if (e.kind === 'tab_created') this.recordChange(id, { kind: 'opened', tab: e.page, tabId: e.tabId, ...(e.url && { url: e.url }) });
          else if (e.kind === 'tab_closed') { this.recordChange(id, { kind: 'closed', tab: e.page, tabId: e.tabId }); this.clearAttention(id, e.page); }
          else if (e.kind === 'tab_released') this.clearAttention(id, e.page);
          else if (e.kind === 'tab_navigated') this.recordChange(id, { kind: 'navigated', tab: e.page, ...(e.url && { url: e.url }) });
        }
      }
      if (e.kind === 'dialog' && e.page) {
        for (const state of this.sessions.values()) if (state.pages.has(e.page) || state.changes.entries.some(c => 'tab' in c && c.tab === e.page)) { this.recordChange(state.id, { kind: 'dialog', tab: e.page, dialogType: e.dialogType, ...(e.message && { message: e.message.slice(0, 200) }) }); break; }
      }
      this.emit('browser-event', e);
    };
    this.bridge?.on('event', onEvent);
    this.unsubscribeBackend = this.browserBackend?.subscribe(onEvent);
    this.bridge?.on('hello', () => this.emit('features-changed', this.features()));
    this.bridge?.on('close', () => { for (const s of this.sessions.values()) { s.browserPage = undefined; s.pages.clear(); } this.emit('features-changed', []); });
  }

  async init(): Promise<void> {
    await this.registry.load();
    if (this.userAdaptersDir) ensureUserSource(this.userAdaptersDir);
  }

  backend(): Backend {
    if (this.browserBackend) return this.browserBackend.available ? this.browserBackend.kind : 'none';
    if (this.bridge?.connected) return 'extension';
    return 'none';
  }
  async browserCommand(action: import('../protocol.js').Command['action'], params: Partial<import('../protocol.js').Command> = {}): Promise<{ data: unknown }> {
    if (this.browserBackend?.command) return this.browserBackend.command(action, params);
    if (this.bridge) return this.bridge.send(action, params);
    throw Object.assign(new Error('This browser capability is unavailable'), { code: 'capability_unavailable' });
  }

  browserAvailable(): boolean { return this.backend() !== 'none'; }
  features(): BrowserFeature[] { if (this.browserBackend) return this.browserBackend.features(); return this.bridge?.connected ? this.bridge.extensionFeatures : []; }
  hasFeature(feature: BrowserFeature): boolean { return this.features().includes(feature); }

  session(id: string): SessionState {
    let s = this.sessions.get(id);
    if (!s) {
      s = { id, createdAt: Date.now(), pages: new Map(), tabLocks: new Map(), enabledSites: new Map(), capabilities: new Set(), observationSeq: 0, observations: new Map(), refFrames: new Map(), webmcpCatalogs: new Map(), lastObserve: new Map(), netLog: new Map(), changes: { seq: 0, entries: [] }, suggestedSites: new Set(), attention: new Map(), actFailures: new Map(), finalized: false };
      this.sessions.set(id, s);
    }
    return s;
  }

  /** One interactive browser page per MCP session (tabs are page identities on it). */
  async getBrowserPage(sessionId: string): Promise<RuntimePage> {
    const s = this.session(sessionId);
    if (s.browserPage) return s.browserPage;
    if (!s.browserPagePromise) {
      s.browserPagePromise = this.createPage({ session: `mcp:${sessionId}`, surface: 'browser' }).then((p) => { s.browserPage = p; return p; }).finally(() => { s.browserPagePromise = undefined; });
    }
    return s.browserPagePromise;
  }

  /** The page object bound to one tab of a session: commands carry the tab's identity, nothing is switched or shared. */
  async pageFor(sessionId: string, pageId: string): Promise<RuntimePage> {
    const s = this.session(sessionId);
    const existing = s.pages.get(pageId);
    if (existing) return existing;
    const page = await this.createPage({ session: `mcp:${sessionId}`, surface: 'browser', page: pageId });
    s.pages.set(pageId, page);
    return page;
  }
  recordChange(sessionId: string, change: SessionChange): void {
    const state = this.sessions.get(sessionId);
    if (!state) return;
    const log = state.changes;
    log.entries.push({ ...change, seq: ++log.seq });
    if (log.entries.length > MAX_CHANGES) log.entries.splice(0, log.entries.length - MAX_CHANGES);
  }
  /** The agent says the tab needs the user (login, block, error page). The embedding browser shows it; the next use of the tab clears it. */
  flagAttention(sessionId: string, page: { id: string; tabId?: number }, issue: PageIssue, atRun: number): void {
    const state = this.session(sessionId);
    state.attention.set(page.id, { ...issue, atRun });
    this.emit('browser-event', { kind: 'attention', session: `mcp:${sessionId}`, page: page.id, ...(page.tabId !== undefined && { tabId: page.tabId }), reason: issue.code, waiting: true, ...(issue.url && { url: issue.url }), ...(issue.note && { note: issue.note }) });
  }
  clearAttention(sessionId: string, pageId: string, tabId?: number): void {
    const state = this.sessions.get(sessionId);
    const issue = state?.attention.get(pageId);
    if (!state || !issue) return;
    state.attention.delete(pageId);
    this.emit('browser-event', { kind: 'attention', session: `mcp:${sessionId}`, page: pageId, ...(tabId !== undefined && { tabId }), reason: issue.code, waiting: false });
  }
  /** What happened in this session since change `from`: tabs opened/closed/navigated, dialogs, issues, and adapters for sites it reached. */
  async changesSince(sessionId: string, from: number): Promise<ChangeSummary | undefined> {
    const state = this.sessions.get(sessionId);
    if (!state) return undefined;
    const entries = state.changes.entries.filter((c) => c.seq > from);
    const opened = new Map<string, { tab: string; url?: string }>();
    const navigated = new Map<string, { tab: string; url?: string }>();
    const closed: string[] = []; const dialogs: Array<{ tab: string; type: string; message?: string }> = []; const issues: Array<PageIssue & { tab: string }> = [];
    for (const c of entries) {
      if (c.kind === 'opened') opened.set(c.tab, { tab: c.tab, ...(c.url && { url: c.url }) });
      else if (c.kind === 'navigated') {
        const into = opened.get(c.tab) ?? navigated.get(c.tab) ?? { tab: c.tab };
        if (c.url) into.url = c.url;
        if (!opened.has(c.tab)) navigated.set(c.tab, into);
      } else if (c.kind === 'closed') { if (!closed.includes(c.tab)) closed.push(c.tab); }
      else if (c.kind === 'dialog') dialogs.push({ tab: c.tab, type: c.dialogType, ...(c.message && { message: c.message }) });
      else if (c.kind === 'toolError' || c.kind === 'fallback') continue;
      else if (c.kind === 'issue' && !issues.some((i) => i.tab === c.tab && i.code === c.issue.code && i.url === c.issue.url && i.source === c.issue.source)) issues.push({ tab: c.tab, ...c.issue });
    }
    const sites = await this.suggestSites(state, [...opened.values(), ...navigated.values()].map((t) => t.url).filter((u): u is string => Boolean(u)));
    const summary: ChangeSummary = {
      ...(opened.size && { opened: [...opened.values()] }),
      ...(navigated.size && { navigated: [...navigated.values()] }),
      ...(closed.length && { closed }),
      ...(dialogs.length && { dialogs: dialogs.slice(0, 8) }),
      ...(issues.length && { issues: issues.slice(0, 8) }),
      ...(sites.length && { sites }),
    };
    return Object.keys(summary).length ? summary : undefined;
  }
  /** Tool errors and fallbacks recorded since change `from`, in call order. Repeats of one error collapse into a count. */
  frictionSince(sessionId: string, from: number): ToolFriction | undefined {
    const state = this.sessions.get(sessionId);
    if (!state) return undefined;
    const toolErrors: Array<ToolError & { count?: number }> = []; const fallbacks: ToolFallback[] = [];
    for (const c of state.changes.entries) {
      if (c.seq <= from) continue;
      if (c.kind === 'toolError') {
        const last = toolErrors[toolErrors.length - 1];
        if (last && last.code === c.error.code && last.api === c.error.api && last.tab === c.error.tab && last.target === c.error.target && last.action === c.error.action) last.count = (last.count ?? 1) + 1;
        else toolErrors.push({ ...c.error });
      } else if (c.kind === 'fallback') fallbacks.push(c.fallback);
    }
    if (!toolErrors.length && !fallbacks.length) return undefined;
    return { ...(toolErrors.length && { toolErrors: toolErrors.slice(0, 12) }), ...(fallbacks.length && { fallbacks: fallbacks.slice(0, 8) }) };
  }
  private async suggestSites(state: SessionState, urls: string[]): Promise<NonNullable<ChangeSummary['sites']>> {
    const out: NonNullable<ChangeSummary['sites']> = [];
    const hosts = urls.map((u) => { try { return new URL(u).hostname.toLowerCase(); } catch { return ''; } }).filter(Boolean);
    if (!hosts.length) return out;
    for (const site of this.registry.sites()) {
      if (state.suggestedSites.has(site.site)) continue;
      if (!site.domains.some((d) => hosts.some((h) => h === d.toLowerCase() || h.endsWith(`.${d.toLowerCase()}`)))) continue;
      state.suggestedSites.add(site.site);
      const commands = (await this.registry.commands(site.site).catch(() => [])).map((c) => c.access === 'write' ? `${c.name} (write)` : c.name);
      out.push({ site: site.site, commands: commands.slice(0, 15), ...(commands.length > 15 && { more: commands.length - 15 }) });
    }
    return out;
  }
  forgetPage(sessionId: string, pageId: string): void {
    const state = this.sessions.get(sessionId);
    if (!state) return;
    state.observations.delete(pageId);
    state.refFrames.delete(pageId);
    state.pages.delete(pageId);
    state.tabLocks.delete(pageId);
    for (const cache of [state.webmcpCatalogs, state.lastObserve]) {
      for (const key of cache.keys()) if (key.startsWith(`${pageId}:`)) cache.delete(key);
    }
  }

  /** Bind each adapter call to the site's current live tab; the extension owns that selection. */
  async getAdapterPage(site: string): Promise<RuntimePage> {
    const caller = this.adapterCallContext.getStore()?.sessionId;
    const key = caller ? `mcp:${caller}` : `site:${site}`;
    const session = await this.createPage({ session: key, surface: 'adapter' });
    const tabs = await session.tabs() as Array<{ page?: string; selected: boolean; state: 'active' | 'handoff' }>;
    const active = tabs.filter((tab) => tab.state === 'active');
    const current = active.find((tab) => tab.selected) ?? active[0];
    if (current && !current.page) throw Object.assign(new Error('Adapter tab is not ready'), { code: 'tab_pending', hint: 'Retry the adapter command when its tab has a page handle.' });
    return current?.page ? this.createPage({ session: key, surface: 'adapter', page: current.page }) : session;
  }

  private async createPage(opts: { session: string; surface: 'browser' | 'adapter'; page?: string }): Promise<RuntimePage> {
    if (this.browserBackend) return this.browserBackend.createPage(opts);
    const backend = this.backend();
    if (backend === 'extension' && this.bridge) return createExtensionPage(this.bridge, opts);
    throw Object.assign(new Error('No browser backend is connected'), { code: 'browser_unavailable', hint: 'Run `browsermcp doctor`. Chrome with the browsermcp extension must be running.' });
  }

  /** Adapters run on the browser object model: a Tab bound to the adapter page, plus sites/recon. */
  async toolContext(page: RuntimePage, site: string): Promise<Record<string, unknown>> {
    const sessionId = this.adapterCallContext.getStore()?.sessionId ?? `site:${site}`;
    let api = this.siteApis.get(sessionId);
    if (!api) { api = createAgentApi(this, sessionId); this.siteApis.set(sessionId, api); }
    const state = this.session(sessionId);
    state.finalized = false;
    const tab = new Tab(page.getActivePage() ?? 'adapter', { rt: this, sessionId, state }, page);
    return { tab, page, sites: api.sites, recon: api.recon };
  }

  isManagedPage(page: RuntimePage): page is ManagedRuntimePage { return typeof (page as ManagedRuntimePage).claim === 'function'; }

  async runSite(site: string, name: string, args: Record<string, unknown>, opts: { timeoutMs?: number; signal?: AbortSignal; sessionId?: string } = {}): Promise<CommandRunResult | CommandRunError> {
    const cmd = await this.registry.resolve(site, name);
    // a session already using this site's commands needs no suggestion of them
    if (opts.sessionId) this.sessions.get(opts.sessionId)?.suggestedSites.add(cmd.site);
    return this.runCommand(cmd, args, opts);
  }

  private async runCommand(cmd: AdapterCommand, args: Record<string, unknown>, opts: { timeoutMs?: number; signal?: AbortSignal; sessionId?: string } = {}): Promise<CommandRunResult | CommandRunError> {
    const site = cmd.site;
    const name = cmd.name;
    const active = this.adapterCallContext.getStore();
    if (active?.retired) return { ok: false, site, name, error: { code: 'command_outcome_unknown', message: 'The parent adapter call has timed out or been cancelled', hint: 'Inspect browser or site state before retrying.' }, elapsedMs: 0 };
    // A nested call into the same site is part of the current workflow and already owns its page.
    if (active?.sites.has(site)) return runAdapter(this, cmd, args, opts);
    const sessionId = opts.sessionId ?? active?.sessionId;
    const lockKey = `${sessionId ?? "legacy"}:${site}`;
    const previous = this.adapterRuns.get(lockKey) ?? Promise.resolve();
    let release!: () => void;
    const current = new Promise<void>((resolve) => { release = resolve; });
    this.adapterRuns.set(lockKey, current);
    await previous;
    try {
      const callContext = { sites: new Set([...(active?.sites ?? []), site]), retired: false, sessionId };
      const result = await this.adapterCallContext.run(callContext, () => runAdapter(this, cmd, args, opts));
      if (!result.ok && result.error.code === 'command_outcome_unknown') {
        callContext.retired = true;
        // Timed-out adapter code may still be running. Retire its page before the next call uses this site.
        const key = sessionId ? `mcp:${sessionId}` : `site:${site}`;
        await this.createPage({ session: key, surface: 'adapter' }).then((p) => p.closeWindow()).catch(() => {});
      }
      return result;
    } finally {
      release();
      if (this.adapterRuns.get(lockKey) === current) this.adapterRuns.delete(lockKey);
    }
  }

  private draftStore(): DraftStore {
    if (!this.drafts) throw Object.assign(new Error('Adapter authoring is disabled by the host'), { code: 'capability_unavailable' });
    return this.drafts;
  }

  listTools(): ReturnType<typeof listDefinedTools> { return this.userAdaptersDir ? listDefinedTools(this.userAdaptersDir) : []; }

  async defineTool(def: ToolDefinition): ReturnType<DraftStore['createDraft']> {
    return this.draftStore().createDraft(def, this.registry.sourceFile(def.site, def.name));
  }
  async tryToolDraft(id: string, args: Record<string, unknown>, expect: DraftExpectation, sessionId?: string): ReturnType<DraftStore['tryDraft']> {
    return this.draftStore().tryDraft((cmd, sample) => this.runCommand(cmd, sample, { sessionId }), id, args, expect);
  }
  async activateToolDraft(id: string): Promise<ReturnType<DraftStore['activateDraft']>> {
    const active = this.draftStore().activateDraft(id, (site, name) => this.registry.sourceFile(site, name));
    await this.registry.load();
    this.emit('tools-changed', { site: active.site });
    return active;
  }
  discardToolDraft(id: string): ReturnType<DraftStore['discardDraft']> { return this.draftStore().discardDraft(id); }
  async removeTool(site: string, name: string): Promise<boolean> {
    this.draftStore();
    const ok = deleteTool(site, name, this.userAdaptersDir!);
    if (ok) { await this.registry.load(); this.emit('tools-changed', { site }); }
    return ok;
  }

  async closeSession(id: string, opts: { finalize?: boolean } = {}): Promise<void> {
    const s = this.sessions.get(id);
    if (!s) return;
    await s.js?.dispose();
    this.sessions.delete(id);
    this.siteApis.delete(id);
    const page = s.browserPage;
    if (page && opts.finalize !== false && !s.finalized) {
      try {
        if (this.isManagedPage(page)) await page.finalize([], { closing: true });
        else await page.closeWindow();
      } catch (err) { this.emit('log', `finalize on close failed: ${(err as Error).message}`); }
    }
  }

  async shutdown(): Promise<void> {
    for (const id of [...this.sessions.keys()]) await this.closeSession(id);
    this.unsubscribeBackend?.();
    await this.browserBackend?.dispose();
  }

  doctor(): DoctorReport {
    const list = this.registry.sites();
    return {
      backend: this.backend(),
      browser: { connected: this.browserAvailable(), features: this.features() },
      extension: { connected: Boolean(this.bridge?.connected), protocolMatches: this.backend() === 'electron' ? null : Boolean(this.bridge?.protocolMatches), protocolWarning: this.bridge?.protocolWarning ?? null, version: this.bridge?.extensionVersion ?? null, protocolRevision: this.bridge?.protocolRevision ?? null, hostProtocolRevision: PROTOCOL_REVISION, features: this.features() },
      sites: list.length,
      commands: list.reduce((n, s) => n + s.commands, 0),
      definedTools: this.listTools().length,
      // Count only real MCP sessions; background adapter contexts are keyed `site:<site>` and are not agents.
      sessions: [...this.sessions.keys()].filter((k) => !k.startsWith('site:')).length,
      cursor: this.cursorEnabled,
    };
  }
}
